// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("research_company",
			mcplib.WithDescription("Research a company by ticker: fetch its consolidated profile page with key metrics, analysis, and financials."),
			mcplib.WithString("symbol", mcplib.Required(), mcplib.Description("Company ticker symbol (e.g. INFY, TCS, RELIANCE)")),
		),
		handleResearchCompany,
	)
	s.AddTool(
		mcplib.NewTool("screen_overlap",
			mcplib.WithDescription("Find companies appearing in two stock screens by intersecting their result tables."),
			mcplib.WithString("screen_a_id", mcplib.Required(), mcplib.Description("First screen numeric id (e.g. 1)")),
			mcplib.WithString("screen_a_slug", mcplib.Required(), mcplib.Description("First screen slug (e.g. the-bull-cartel)")),
			mcplib.WithString("screen_b_id", mcplib.Required(), mcplib.Description("Second screen numeric id (e.g. 59)")),
			mcplib.WithString("screen_b_slug", mcplib.Required(), mcplib.Description("Second screen slug (e.g. magic-formula)")),
		),
		handleScreenOverlap,
	)
	s.AddTool(
		mcplib.NewTool("high_conviction_screen_intersection",
			mcplib.WithDescription("Companies passing both a value formula and a growth screen"),
			mcplib.WithString("id", mcplib.Required(), mcplib.Description("Override the recipe's positional id value.")),
			mcplib.WithString("slug", mcplib.Required(), mcplib.Description("Override the recipe's positional slug value.")),
			mcplib.WithString("id2", mcplib.Required(), mcplib.Description("Override the recipe's positional id value.")),
			mcplib.WithString("slug2", mcplib.Required(), mcplib.Description("Override the recipe's positional slug value.")),
		),
		handleHighConvictionScreenIntersection,
	)
}

// handleResearchCompany runs the research_company intent: Research a company by ticker: fetch its consolidated profile page with key metrics, analysis, and financials.
